5	
6	// A conta. Liga-se a uma linha do cadastro elegível, uma para uma (um RA, uma conta), e é
7	// de lá que vem o papel. Aluno se cadastra pelo app; professor e instituição nascem do
8	// seed sem senha e definem a primeira pela recuperação (produto.md 2.5). Desde o passo 12, o
9	// aluno do mundo da demonstração também nasce do seed, sem senha (CriarAlunoPeloSeed).
10	public sealed class Usuario
11	{
12	    private readonly List<PrefixoReservado> _prefixosReservados = [];
13	    private readonly List<AceiteDeTermo> _aceitesDeTermo = [];
14	
15	    // Para o EF Core materializar do banco.
