17	    {
18	        NomeDeExibicao = null!;
19	        Prefixo = null!;
20	        Sufixo = null!;
21	    }
22	
23	    private Usuario(
24	        CadastroElegivel cadastro, string nomeDeExibicao, string prefixo, string sufixo, string? hashDaSenha, DateTimeOffset agora)
25	    {
26	        Id = Guid.CreateVersion7();
27	        CadastroElegivelId = cadastro.Id;
28	        Papeis = cadastro.Papeis;
